const oldHousingDetail=v3HousingDetail;v3HousingDetail=function(h){const idx=V3.housing.selected===h.id?Number(V3.housing.room||0):0;const room=h.rooms[idx]||h.rooms[0];let html=oldHousingDetail(h);const rows=h.rooms.map((x,i)=>`<tr><th>${t('Zimmer','Room')} ${esc(x.source_room_label)}${h.rooms.filter(y=>y.source_room_label===x.source_room_label).length>1?` <small>(${i+1})</small>`:''}</th><td>${x.area_m2_html_counter_target} m²</td><td>${x.monthly_eur} €${x.per_person?' / '+t('Person','person'):''}</td></tr>`).join('');const block=`<h3>${t('Zimmer im Überblick','Rooms at a glance')}</h3><div class="v3-table-wrap"><table class="v3-compare-table"><thead><tr><th>${t('Zimmer','Room')}</th><th>${t('Fläche laut Website','Published area')}</th><th>${t('Monatlicher Orientierungspreis','Indicative monthly rate')}</th></tr></thead><tbody>${rows}</tbody></table></div>`;html=html.replace('<h3>'+t('So geht es weiter','What happens next')+'</h3>',block+'<h3>'+t('So geht es weiter','What happens next')+'</h3>');html=html.replace('<label class="field">'+t('Gewünschter Einzug','Preferred move-in'),`<label class="field">${t('Zimmerauswahl','Room selection')}<select id="v3-room-select" data-property="${h.id}">${h.rooms.map((x,i)=>`<option value="${i}" ${i===idx?'selected':''}>${t('Zimmer','Room')} ${x.source_room_label} · ${x.area_m2_html_counter_target} m² · ${x.monthly_eur} €${x.per_person?' / '+t('Person','person'):''}</option>`).join('')}</select></label><label class="field">`+t('Gewünschter Einzug','Preferred move-in'));return html};
