function v3Exam(r){if(r==='/pruefungszentrum'||r==='/pruefungszentrum/termine')return `<section class="v3-page-intro"><span class="eyebrow">WAY2GERMANY PRÜFUNGSZENTRUM</span><h1>${t('Zeig, was du kannst.','Show what you can do.')}</h1><p>${t('Sprachkenntnisse und Studieneignung nachweisen. Finde deine Prüfung und den passenden Anmeldeweg.','Demonstrate your language skills and academic aptitude. Find your examination and registration pathway.')}</p></section>${v3Section(t('DEINE PRÜFUNG','YOUR EXAMINATION'),t('Welcher Nachweis ist dein nächster Schritt?','Which certificate is your next step?'),`<div class="v3-card-grid two">${EXAM_CONTENT.map(e=>v3Card(e.name,t(e.de,e.en),'/pruefungszentrum/'+e.id,t('Prüfung kennenlernen','Explore examination'))).join('')}</div>`)}${v3Section(t('TERMINE & ANMELDUNG','DATES & REGISTRATION'),t('Plane deinen Prüfungstermin.','Plan your exam date.'),`<p>${t('Die Terminübersicht und einzelne Prüfungsseiten nennen teilweise unterschiedliche Daten. Lass deinen Wunschtermin bestätigen, bevor du deine Reise oder Anmeldung planst.','The schedule and individual exam pages list some different dates. Confirm your preferred date before planning travel or registration.')}</p>${link(t('Termin persönlich klären','Confirm a date with the team'),'/beratung','secondary')}<p class="v3-source-note"><a href="https://w2g-pruefungen.de/termine/" target="_blank" rel="noopener">${t('Terminseite des Prüfungszentrums','Examination centre schedule')}</a> · ${t('Quellstand','Captured')} 30.10.2026</p>`)}`;const id=r.split('/')[2];if(!['dmat','onset','testas','testdaf'].includes(id)||r.split('/').length>3)return null;const e=EXAM_CONTENT.find(x=>x.id===id),external=id==='testas'?'https://www.testas.de/de/teilnehmende/mein-testas/testas-termine-und-anmeldung':id==='testdaf'?'https://www.testdaf.de/de/teilnehmende/mein-testdaf/testdaf-termine-und-anmeldung/':null;return `<div class="v3-breadcrumb"><a href="#/pruefungszentrum">${t('Prüfungszentrum','Examination centre')}</a> / ${e.name}</div><section class="v3-page-intro"><span class="eyebrow">WAY2GERMANY PRÜFUNGSZENTRUM</span><h1>${e.name}</h1><p>${t(e.de,e.en)}</p></section>${v3Section(t('GUT ZU WISSEN','GOOD TO KNOW'),id==='onset'?t('Aktuell kein Prüfungstermin veröffentlicht.','No examination currently published.'):t('Vorbereitung und Anmeldung.','Preparation and registration.'),`<p>${id==='dmat'?t('Die bestehende Website beschreibt ein Kernmodul und ein fachspezifisches Modul. Der Test ist dort als englischsprachiger, digitaler Nachweis für internationale Masterinteressenten beschrieben; Termine sind nicht veröffentlicht. Voraussetzungen bitte beim Prüfungszentrum klären.','The existing website describes a core module and a subject-specific module. It describes an English-language digital test for international master’s applicants; no dates are published. Confirm requirements with the examination centre.'):id==='onset'?t('Die onSET-Seite des Prüfungszentrums nennt derzeit kein Angebot. Frage nach, wenn du einen Sprachnachweis für deinen konkreten Weg benötigst.','The examination centre’s onSET page currently lists no offering. Ask the team if you need language evidence for your specific pathway.'):t('Die Anmeldung läuft über den offiziellen Anbieter. Vorbereitung, Terminwahl und erforderlicher Nachweis sollten zu deinem Bildungsziel passen. Eine Beratungsanfrage ist keine Prüfungsanmeldung.','Registration is handled by the official provider. Preparation, dates and required evidence should match your educational goal. A guidance enquiry is not exam registration.')}</p><div class="actions">${external?`<a class="btn" href="${external}" target="_blank" rel="noopener">${t('Offizielle Termine & Anmeldung','Official dates & registration')}${arrow}</a>`:''}${link(t('Beratung anfragen','Ask for guidance'),'/beratung','secondary')}</div><p class="v3-source-note"><a href="https://w2g-pruefungen.de/${id}/" target="_blank" rel="noopener">${t('Angaben des Prüfungszentrums','Examination centre information')}</a> · 30.10.2026</p>`)}`}
const beforeExamBody=v3Body;v3Body=function(r){if(r.startsWith('/pruefungszentrum')){const content=v3Exam(r);if(content)return content}return beforeExamBody(r)};
