portalContent=function(role,view){if(role!=='applicant'||view!=='overview')return originalPortalContent(role,view);const n=Object.keys(state.uploads).length,complete=n===3;return `<span class="eyebrow">${t('DEINE BEWERBUNG','YOUR APPLICATION')} · DEMO-001</span><h1>${t('Dein Weg nimmt Form an.','Your path is taking shape.')}</h1><p class="intro">${t('Willkommen, Alex Beispiel. Hier behältst du deine Bewerbung im Blick.','Welcome, Alex Sample. Follow your application here.')}</p>${panel(t('Dein aktueller Stand','Your current status'),`<div class="task-row"><strong>${esc(state.application.course)} · ${esc(applicationChoiceLabel(state.application.language))}</strong>${badge(complete?t('Zur Prüfung vorbereitet','Prepared for review'):t('Unterlagen ergänzen','Add documents'),'blue')}</div><div class="progress"><span style="width:${complete?60:25+n*10}%"></span></div><p>${complete?t('Alle drei Musterunterlagen sind vorhanden. Dein Entwurf ist für den nächsten Prüfschritt vorbereitet; es wurde nichts eingereicht und noch keine Zulassungsentscheidung getroffen.','All three sample documents are present. Your draft is ready for the next review step; nothing was submitted and no admission decision has been made.'):t(`Du hast ${n} von 3 Musterunterlagen ergänzt. Öffne deine Dokumentenmappe, um die fehlenden Unterlagen zu sehen.`,`You have added ${n} of 3 sample documents. Open your document folder to see what is missing.`)}</p>${applicationDraftDetails()}${link(t('Meine Dokumente','My documents'),'/portal/applicant/documents','secondary')}`)}<div class="info-grid" style="margin-top:24px">${panel(t('Deine nächsten Schritte','Your next steps'),complete?`<p>${t('Bereite offene Fragen für das persönliche Gespräch vor.','Prepare any open questions for your advisory conversation.')}</p>${button(t('Termin auswählen','Choose appointment'),'appointment','secondary')}`:taskRows('applicant'))}${panel(t('Dein Beratungsbrief','Your guidance brief'),`<p>${esc(V2.notes['visitor:journey']?.brief)||t('Hier kannst du deine Fragen für die Beratung sammeln.','Collect your questions for the advisory team here.')}</p>${button(t('Brief bearbeiten','Edit brief'),'brief','secondary')}`)}</div>`};
